import { defineFormats, setLocale } from '@pyreon/format'
import { Num } from '@pyreon/format/components'

const f = defineFormats({
  price: { kind: 'currency', currency: 'EUR' },
  size: { kind: 'bytes' },
})

const Row = (props: { name: string; price: number; bytes: number }) => (
  <tr>
    <td>{props.name}</td>
    <td>{f.price(props.price)}</td>
    <td><Num value={props.bytes} kind="bytes" /></td>
  </tr>
)

// <Row name="Export" price={1234.5} bytes={1536} />
// en-US: "€1,234.50"   "1.5 kB"
setLocale('de')
// de:    "1.234,50 €"   "1,5 kB"
setLocale('ja')
// ja:    "€1,234.50"   "1.5 KB"

import { formatCurrency, parseNumber } from '@pyreon/format'
import { computed, signal } from '@pyreon/reactivity'

const typed = signal('1 234,5')
const amount = computed(() => parseNumber(typed(), { locale: 'cs' }))

// <input value={typed()} onInput={(e) => typed.set(e.currentTarget.value)} />
