amount()                                  // 1234.5  →  "1 234,50 Kč"
parseNumber('1.234', { locale: 'de' })    // 1234
parseNumber('1.234', { locale: 'en-US' }) // 1.234
parseNumber('twelve', { locale: 'en-US' }) // null

import { bytesFormatter, currencyFormatter, listFormatter, percentFormatter } from '@pyreon/format'

const price = currencyFormatter('EUR', { locale: 'en-US' })
price(9.99)                                        // "€9.99"
price.range(10, 20)                                // "€10.00 – €20.00"
price.with({ maximumFractionDigits: 0 })(9.99)     // "€10"  (price itself is untouched)

const fromCents = price.from((cents: number) => cents / 100)
fromCents(999)                                     // "€9.99"
;[999, 1250].map(fromCents)                        // ["€9.99", "€12.50"]
listFormatter({ locale: 'en-US' })([1250, 2500].map(fromCents))   // "€12.50 and €25.00"

const size = bytesFormatter({ locale: 'en-US' })
const pct = percentFormatter({ locale: 'en-US' })
`${size(1536)} of ${size(4096)} (${pct(1536 / 4096)})`   // "1.5 kB of 4.1 kB (38%)"
